CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin','member')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE sessions (hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE api_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, hash TEXT NOT NULL UNIQUE, prefix TEXT NOT NULL, scopes JSONB NOT NULL, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_used_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ);
CREATE TABLE invitations (id TEXT PRIMARY KEY, hash TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), expires_at TIMESTAMPTZ NOT NULL, used_at TIMESTAMPTZ);
CREATE TABLE members (id TEXT PRIMARY KEY, name TEXT NOT NULL, surname TEXT NOT NULL DEFAULT '', profile_url TEXT NOT NULL DEFAULT '', cohort TEXT NOT NULL DEFAULT 'new', active BOOLEAN NOT NULL DEFAULT true, notes TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX members_profile_unique ON members(lower(profile_url)) WHERE profile_url <> '';
CREATE TABLE records (id TEXT PRIMARY KEY, island TEXT NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', member_id TEXT REFERENCES members(id) ON DELETE RESTRICT, assignee_id TEXT REFERENCES users(id) ON DELETE RESTRICT, due_date DATE, event_date DATE NOT NULL, status TEXT NOT NULL DEFAULT 'pending', priority TEXT NOT NULL DEFAULT 'medium', next_action TEXT NOT NULL DEFAULT '', evidence_url TEXT NOT NULL DEFAULT '', official_url TEXT NOT NULL DEFAULT '', verification TEXT NOT NULL DEFAULT 'pending', review_note TEXT NOT NULL DEFAULT '', points INTEGER NOT NULL DEFAULT 0 CHECK(points>=0), data JSONB NOT NULL DEFAULT '{}', version INTEGER NOT NULL DEFAULT 1, created_by TEXT NOT NULL REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE INDEX records_island ON records(island,created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX records_member ON records(member_id) WHERE deleted_at IS NULL;
CREATE TABLE audit_events (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), token_id TEXT REFERENCES api_tokens(id), action TEXT NOT NULL, entity_id TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE idempotency_keys (key TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES users(id), request_hash TEXT NOT NULL, response JSONB NOT NULL, status INTEGER NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), PRIMARY KEY(key,user_id));
INSERT INTO schema_migrations(version) VALUES ('001-initial');
